    unsafe { arch::_mm512_storeu_si512(buf.as_mut_ptr().add(17).cast(), m512(a)) };
    assert!(buf[..17].iter().chain(&buf[81..]).all(|&x| x == SENTINEL), "_mm512_storeu_si512 wrote outside its 64 bytes");
