/// `_mm256_storeu_si256` into an unaligned slot of a sentinel-filled buffer; returns the 32 bytes written and
/// panics if any byte outside them changed.
#[target_feature(enable = "avx")]
pub fn _mm256_storeu_si256(a: [u8; 32]) -> [u8; 32] {
    let mut buf = [SENTINEL; 66];
    // SAFETY: `buf[17..49]` is in bounds and writable; the store has no alignment requirement.
    unsafe { arch::_mm256_storeu_si256(buf.as_mut_ptr().add(17).cast(), m256(a)) };
    assert!(buf[..17].iter().chain(&buf[49..]).all(|&x| x == SENTINEL), "_mm256_storeu_si256 wrote outside its 32 bytes");
    buf[17..49].try_into().expect("32 bytes")
}

